    {"claim": "Extend the telemetry-for-liability-protection trade to deployers: high-stakes integrators log runtime behavior at the interface in exchange for liability protection.", "targets": ["AN-Skeptic-final"]},
    {"claim": "Ecommerce alone runs over $20 trillion in transactions worldwide, so blanket recordkeeping duties on every integrator would kill open-weight deployment.", "targets": ["AN-Skeptic-final"]},
    {"claim": "The Skeptic's candor metric and gap argument run on contradictory premises about the same deployer-side data — it cannot be both complete and missing.", "targets": ["AN-Skeptic-final"]}
  ]
}

